<?php $borrowers=$pdo->query("SELECT id,full_name FROM borrowers WHERE status='Active' ORDER BY full_name")->fetchAll();$cats=$pdo->query('SELECT id,name FROM equipment_categories ORDER BY name')->fetchAll();$error='';verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$bid=(int)($_POST['borrower_id']??0);$cid=(int)($_POST['category_id']??0);$qty=(int)($_POST['quantity']??0);$start=$_POST['start_date']??'';$due=$_POST['due_date']??'';if(!$bid||!$cid||$qty<1||$qty>20||!preg_match('/^\d{4}-\d\d-\d\d$/',$start)||!preg_match('/^\d{4}-\d\d-\d\d$/',$due)||$due<$start)$error='Choose a borrower, category, quantity and valid date range.';else{$s=$pdo->prepare("SELECT COUNT(*) FROM borrowers WHERE id=? AND status='Active'");$s->execute([$bid]);if(!$s->fetchColumn())$error='Select an active borrower.';else{$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO loan_requests(borrower_id,category_id,quantity,start_date,due_date,notes,created_by) VALUES(?,?,?,?,?,?,?)');$s->execute([$bid,$cid,$qty,$start,$due,trim($_POST['notes']??''),user()['id']]);$rid=(int)$pdo->lastInsertId();$s=$pdo->prepare('INSERT INTO request_items(request_id,category_id) VALUES(?,?)');for($i=0;$i<$qty;$i++)$s->execute([$rid,$cid]);log_activity($pdo,'Created loan request','request',$rid);$pdo->commit();flash('Loan request created.');redirect('?page=request-view&id='.$rid);}}}layout_start('Create loan request','requests'); ?><div class="page-heading"><div><a class="back-link" href="?page=requests">← Loan requests</a><h1>Create a loan request</h1><p class="muted">Request equipment for a registered borrower.</p></div></div><?php if($error): ?><div class="alert error"><?=h($error)?></div><?php endif; ?><?php if(!$borrowers): ?><div class="alert warning">Register an active borrower before creating a request.</div><?php endif; ?><section class="panel form-panel"><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label class="span-two">Borrower<select required name="borrower_id"><option value="">Choose a borrower</option><?php foreach($borrowers as $b): ?><option value="<?=$b['id']?>" <?=((int)($_GET['borrower']??$_POST['borrower_id']??0)===$b['id'])?'selected':''?>><?=h($b['full_name'])?></option><?php endforeach; ?></select></label><label>Equipment category<select required name="category_id"><option value="">Choose category</option><?php foreach($cats as $c): ?><option value="<?=$c['id']?>" <?=((int)($_POST['category_id']??0)===$c['id'])?'selected':''?>><?=h($c['name'])?></option><?php endforeach; ?></select></label><label>Quantity<input type="number" min="1" max="20" required name="quantity" value="<?=h($_POST['quantity']??1)?>"></label><label>Requested start date<input type="date" name="start_date" required value="<?=h($_POST['start_date']??date('Y-m-d'))?>"></label><label>Expected return date<input type="date" name="due_date" required value="<?=h($_POST['due_date']??date('Y-m-d',strtotime('+14 days')))?>"></label><label class="span-two">Request notes<textarea name="notes" rows="3"><?=h($_POST['notes']??'')?></textarea></label><div class="form-actions span-two"><a class="button ghost" href="?page=requests">Cancel</a><button class="button primary" <?=$borrowers?'':'disabled'?>>Submit request</button></div></form></section><?php layout_end();
